// 24-S5 acceptance: the collaborator migration is additive. Applied to a
// schema holding synthetic rows, it preserves every row and timestamp and
// adds two empty tables, constrained to one membership per account and
// puzzle and one invitation per address and puzzle, each going with its
// puzzle (and a membership with its account). Do not edit this file to match
// an implementation.
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { createTestDatabase, migrationNames, type TestDatabase } from '@/test-support/database';

const NAME = /_add_puzzle_collaborators$/;

let db: TestDatabase;
beforeAll(async () => {
  const names = await migrationNames();
  const index = names.findIndex((name) => NAME.test(name));
  db = await createTestDatabase({ holdBack: index < 0 ? 0 : names.length - index });
}, 60_000);
afterAll(async () => { await db?.drop(); });

const rows = async (table: string, order = 'id') =>
  (await db.query(`SELECT to_jsonb(t) AS row FROM "${table}" t ORDER BY ${order}`)).rows.map(({ row }) => row);

describe('24-S5-8 the collaborator migration', () => {
  it('is the newest, preserves every row, and adds two empty tables', async () => {
    expect((await migrationNames()).at(-1)).toMatch(NAME);

    await db.query(`INSERT INTO "user" (id, name, email, "updatedAt", "displayName") VALUES
      ('owner', 'Owner', 'owner@24s5.example.test', '2024-01-02', 'Owner'),
      ('jay', 'Jay', 'jay@24s5.example.test', '2024-01-03', 'Jay')`);
    await db.query(`INSERT INTO "Puzzle"
      (id, "builderId", title, grid, hints, phase, "gridBeforeHints", "publishedAt", visibility, "createdAt", "updatedAt", version, "resetEpoch") VALUES
      ('draft', 'owner', 'Draft', '{"cols":1,"rows":1,"cells":[[{"kind":"active","letter":"A"}]]}', '{}', 'grid', NULL, NULL, 'private', '2024-01-01', '2024-02-02', 4, 1),
      ('done', 'owner', 'Done', '{"cols":1,"rows":1,"cells":[[{"kind":"black"}]]}', '{"1-across":"Clue"}', 'hints', '{"original":"grid"}', '2024-03-04', 'public', '2024-01-03', '2024-02-04', 0, 0)`);
    await db.query(`INSERT INTO "PlaySession" (id, "userId", "puzzleId", entries, "startedAt")
      VALUES ('play', 'jay', 'done', '{"cells":[]}', '2024-03-05')`);
    await db.query(`INSERT INTO "PuzzleOperation" (id, "puzzleId", "opId", "userId", "clientId", epoch, "baseVersion", status, version, operation, "createdAt")
      VALUES ('op', 'draft', 'op-1', 'owner', 'tab', 1, 3, 'accepted', 4, '{"kind":"title","title":"Draft"}', '2024-02-02')`);
    const before = {
      puzzles: await rows('Puzzle'), users: await rows('user'), plays: await rows('PlaySession'), ops: await rows('PuzzleOperation'),
    };

    await db.migrateRest();

    expect(await rows('Puzzle')).toEqual(before.puzzles);
    expect(await rows('user')).toEqual(before.users);
    expect(await rows('PlaySession')).toEqual(before.plays);
    expect(await rows('PuzzleOperation')).toEqual(before.ops);
    expect(await rows('PuzzleCollaborator', '"puzzleId"')).toEqual([]);
    expect(await rows('PuzzleInvitation')).toEqual([]);
  });

  it('one membership per account and puzzle, one invitation per address and puzzle; each goes with its puzzle, a membership with its account', async () => {
    await db.query(`INSERT INTO "PuzzleCollaborator" ("puzzleId", "userId") VALUES ('draft', 'jay'), ('done', 'jay')`);
    await expect(db.query(`INSERT INTO "PuzzleCollaborator" ("puzzleId", "userId") VALUES ('draft', 'jay')`)).rejects.toMatchObject({ code: '23505' });
    await expect(db.query(`INSERT INTO "PuzzleCollaborator" ("puzzleId", "userId") VALUES ('missing', 'jay')`)).rejects.toMatchObject({ code: '23503' });
    await db.query(`INSERT INTO "PuzzleInvitation" (id, "puzzleId", email, "expiresAt") VALUES
      ('i1', 'draft', 'a@example.test', '2030-01-01'), ('i2', 'done', 'a@example.test', '2030-01-01')`);
    await expect(db.query(`INSERT INTO "PuzzleInvitation" (id, "puzzleId", email, "expiresAt") VALUES ('i3', 'draft', 'a@example.test', '2030-01-01')`))
      .rejects.toMatchObject({ code: '23505' });

    await db.query(`DELETE FROM "PlaySession"`);
    await db.query(`DELETE FROM "Puzzle" WHERE id = 'draft'`);
    expect((await rows('PuzzleCollaborator', '"puzzleId"')).map((row) => row.puzzleId)).toEqual(['done']);
    expect((await rows('PuzzleInvitation')).map((row) => row.id)).toEqual(['i2']);

    await db.query(`DELETE FROM "user" WHERE id = 'jay'`);
    expect(await rows('PuzzleCollaborator', '"puzzleId"')).toEqual([]);
    expect((await rows('PuzzleInvitation')).map((row) => row.id)).toEqual(['i2']);
    expect((await rows('Puzzle')).map((row) => row.id)).toEqual(['done']);
  });
});
